/* VDRPros Vault staff screens. Talks to /api/admin/*; the session is a signed cookie set after signing in with an email and password (or the staff key, for the first account and recovery). */
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmtN = n => Number(n || 0).toLocaleString('en-US');
  const fmtB = n => { n = +n || 0; if (n < 1024) return n + ' B'; if (n < 1048576) return (n / 1024).toFixed(1) + ' KB'; if (n < 1073741824) return (n / 1048576).toFixed(1) + ' MB'; return (n / 1073741824).toFixed(2) + ' GB'; };
  const fmtT = t => t ? new Date(+t).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }) : '';
  const state = { signedIn: false, session: null, setupNeeded: false, keyConfigured: true, overview: null, tenants: [] };

  async function api(path, opts = {}) {
    const r = await fetch('/api/admin' + path, { method: opts.method || (opts.body !== undefined ? 'POST' : 'GET'), headers: opts.raw ? {} : { 'Content-Type': 'application/json' }, body: opts.raw ? opts.body : opts.body !== undefined ? JSON.stringify(opts.body) : undefined });
    let j = null; try { j = await r.json(); } catch { j = null; }
    if (r.status === 401 && !opts.quiet) { if (state.signedIn) { state.signedIn = false; state.session = null; render(); } throw new Error((j && j.error) || 'Sign in first'); }
    if (r.status === 403 && j && j.code === 'must_change') { if (state.session) state.session.mustChange = true; render(); throw new Error(j.error); }
    if (!r.ok) { const e = new Error((j && j.error) || 'Request failed'); e.code = j && j.code; e.issues = j && j.issues; e.status = r.status; throw e; }
    return j;
  }
  function toast(msg, cls = '') { const t = document.createElement('div'); t.className = 'toast ' + cls; t.textContent = msg; $('#toasts').appendChild(t); setTimeout(() => t.remove(), 4200); }
  function modal(html, onMount) {
    const root = $('#modalRoot'); root.innerHTML = `<div class="modal-bg"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;
    const bg = $('.modal-bg', root); bg.addEventListener('click', e => { if (e.target === bg) closeModal(); });
    $$('[data-close]', root).forEach(b => b.addEventListener('click', closeModal));
    if (onMount) onMount(root);
    const f = $('input, select, textarea, button', root); if (f) f.focus();
  }
  function closeModal() { $('#modalRoot').innerHTML = ''; }
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });
  const route = () => { const h = location.hash.replace(/^#\/?/, ''); const [path, q] = h.split('?'); const parts = path.split('/').filter(Boolean); return { name: parts[0] || 'overview', id: parts[1] || null, query: Object.fromEntries(new URLSearchParams(q || '')) }; };

  // ---------- shell ----------
  function render() {
    const app = $('#app');
    if (!state.signedIn) { app.innerHTML = signInHtml(); wireSignIn(); return; }
    if (state.session && state.session.via === 'key' && state.setupNeeded) { app.innerHTML = setupHtml(); wireSetup(); return; }
    if (state.session && state.session.staff && state.session.staff.mustChange) { app.innerHTML = changePasswordHtml(true); wireChangePassword(true); return; }
    const r = route();
    app.innerHTML = `<div class="shell"><aside class="side"><div class="brand"><span class="mark"></span><div><b>VDRPros Vault</b><span>Staff</span></div></div>
      <nav class="nav">${[['', 'Overview'], ['tenants', 'Tenants and people'], ['workspaces', 'Workspaces'], ['connections', 'Connections'], ['dead-letters', 'Dead letters'], ['staff', 'Staff']].map(([k, l]) => `<a href="#/${k}" class="${(r.name === (k || 'overview')) ? 'on' : ''}">${l}</a>`).join('')}
        <h4>Help</h4><a href="https://vault.vdrpros.com/api/health" target="_blank" rel="noopener">Health</a></nav>
      <div class="side-foot"><div class="who">${state.session && state.session.staff ? `<b>${esc(state.session.staff.name || state.session.staff.email)}</b><span class="mono">${esc(state.session.staff.email)}</span><span class="muted">${esc(state.session.staff.role)}</span>` : '<b>Staff key</b><span class="muted">recovery session</span>'}</div><div class="row" style="gap:6px;margin-top:8px">${state.session && state.session.staff ? '<button type="button" class="btn sm" id="chPw">Change password</button>' : ''}<button type="button" class="btn sm" id="signOut">Sign out</button></div></div></aside><main class="main" id="main"></main></div>`;
    $('#signOut').addEventListener('click', async () => { await api('/session', { method: 'DELETE' }); state.signedIn = false; state.session = null; render(); });
    $('#chPw')?.addEventListener('click', () => modal(changePasswordHtml(false, true), root => wireChangePassword(false, root)));
    const main = $('#main');
    ({ overview: viewOverview, tenants: viewTenants, tenant: viewTenant, workspaces: viewWorkspaces, workspace: viewWorkspace, batch: viewBatch, connections: viewConnections, 'dead-letters': viewDeadLetters, document: viewDocument, staff: viewStaff }[r.name] || viewOverview)(main, r).catch(e => { main.innerHTML = `<div class="panel">${esc(e.message)}</div>`; });
  }
  function signInHtml() {
    const key = state.useKey;
    return `<div class="signin panel"><div class="brand"><span class="mark"></span><div><b>VDRPros Vault</b><span>Staff sign-in</span></div></div>
      ${key
        ? `<p class="muted small">The staff key set on the Vault service creates the first owner account and gets you back in when nobody can sign in. The session lasts twelve hours.</p><div class="field"><label for="key">Staff key</label><input type="password" id="key" autocomplete="off"></div>`
        : `<p class="muted small">Sign in with your staff email and password. The session lasts twelve hours.</p><div class="field"><label for="email">Email</label><input type="email" id="email" autocomplete="username"></div><div class="field"><label for="pw">Password</label><input type="password" id="pw" autocomplete="current-password"></div>`}
      <button class="btn primary" id="go">Sign in</button>
      <div class="small muted" id="err" style="margin-top:8px"></div>
      <p class="small muted" style="margin-top:14px">${key ? '<a href="#" id="useEmail">Sign in with email and password instead</a>' : (state.keyConfigured ? '<a href="#" id="useKey">No account yet, or locked out? Use the staff key</a>' : 'No staff key is set on the service; an owner has to add you.')}</p></div>`;
  }
  function wireSignIn() {
    const go = async () => {
      $('#err').textContent = '';
      try {
        const r = state.useKey ? await api('/session', { body: { key: $('#key').value } }) : await api('/session', { body: { email: $('#email').value, password: $('#pw').value } });
        await loadSession();
        if (r.via === 'key' && !state.setupNeeded && r.staff === undefined) toast('Signed in with the staff key. Add your own account under Staff when you can.');
        render();
      } catch (e) { $('#err').textContent = e.message; }
    };
    $('#go').addEventListener('click', go);
    $$('input', $('#app')).forEach(i => i.addEventListener('keydown', e => { if (e.key === 'Enter') go(); }));
    $('#useKey')?.addEventListener('click', e => { e.preventDefault(); state.useKey = true; render(); });
    $('#useEmail')?.addEventListener('click', e => { e.preventDefault(); state.useKey = false; render(); });
    ($('#email') || $('#key')).focus();
  }
  function setupHtml() {
    return `<div class="signin panel"><div class="brand"><span class="mark"></span><div><b>VDRPros Vault</b><span>Create the first staff account</span></div></div>
      <p class="muted small">You are in with the staff key. Create your own account now: from then on you sign in with this email and password, and you can add the rest of the team under Staff. The key stays as the recovery path.</p>
      <div class="field"><label for="suEmail">Your email</label><input type="email" id="suEmail" autocomplete="username"></div>
      <div class="field"><label for="suName">Your name</label><input type="text" id="suName" maxlength="120"></div>
      <div class="field"><label for="suPw">Password (at least 12 characters)</label><input type="password" id="suPw" autocomplete="new-password"></div>
      <div class="field"><label for="suPw2">Password again</label><input type="password" id="suPw2" autocomplete="new-password"></div>
      <div class="row" style="gap:8px"><button class="btn primary" id="suGo">Create my account</button><button class="btn" id="suLater">Later</button></div>
      <div class="small muted" id="err" style="margin-top:8px"></div></div>`;
  }
  function wireSetup() {
    const go = async () => {
      $('#err').textContent = '';
      if ($('#suPw').value !== $('#suPw2').value) { $('#err').textContent = 'The two passwords differ'; return; }
      try { await api('/staff/setup', { body: { email: $('#suEmail').value, name: $('#suName').value, password: $('#suPw').value } }); await loadSession(); toast('Your account is ready'); render(); } catch (e) { $('#err').textContent = e.message; }
    };
    $('#suGo').addEventListener('click', go);
    $('#suLater').addEventListener('click', () => { state.setupNeeded = false; render(); });
    $$('input', $('#app')).forEach(i => i.addEventListener('keydown', e => { if (e.key === 'Enter') go(); }));
    $('#suEmail').focus();
  }
  function changePasswordHtml(forced, inModal) {
    const inner = `${forced ? '<p class="muted small">You signed in with a temporary password. Choose your own before going on.</p>' : '<p class="muted small">Every other session of yours is signed out when the password changes.</p>'}
      <div class="field"><label for="cpCur">${forced ? 'Temporary password' : 'Current password'}</label><input type="password" id="cpCur" autocomplete="current-password"></div>
      <div class="field"><label for="cpNew">New password (at least 12 characters)</label><input type="password" id="cpNew" autocomplete="new-password"></div>
      <div class="field"><label for="cpNew2">New password again</label><input type="password" id="cpNew2" autocomplete="new-password"></div>
      <div class="${inModal ? 'modal-actions' : 'row'}" style="gap:8px">${inModal ? '<button class="btn" data-close>Cancel</button>' : ''}<button class="btn primary" id="cpGo">Set password</button></div>
      <div class="small muted" id="cpErr" style="margin-top:8px"></div>`;
    return inModal ? `<h2>Change password</h2>${inner}` : `<div class="signin panel"><div class="brand"><span class="mark"></span><div><b>VDRPros Vault</b><span>Set a new password</span></div></div>${inner}</div>`;
  }
  function wireChangePassword(forced, root = document) {
    const go = async () => {
      $('#cpErr', root).textContent = '';
      if ($('#cpNew', root).value !== $('#cpNew2', root).value) { $('#cpErr', root).textContent = 'The two passwords differ'; return; }
      try { await api('/session/password', { body: { current: $('#cpCur', root).value, next: $('#cpNew', root).value } }); await loadSession(); if (!forced) closeModal(); toast('Password set'); render(); } catch (e) { $('#cpErr', root).textContent = e.message; }
    };
    $('#cpGo', root).addEventListener('click', go);
    $$('input', root).forEach(i => i.addEventListener('keydown', e => { if (e.key === 'Enter') go(); }));
    $('#cpCur', root).focus();
  }
  async function loadSession() {
    try { const r = await api('/session', { quiet: true }); state.signedIn = !!r.signedIn; state.session = r.signedIn ? r : null; state.setupNeeded = !!r.setupNeeded; state.keyConfigured = !!r.keyConfigured; }
    catch { state.signedIn = false; state.session = null; }
  }

  // ---------- staff ----------
  async function viewStaff(main) {
    const r = await api('/staff');
    const roleTag = x => `<span class="tag ${x.role === 'owner' ? 'acc' : ''}">${esc(x.role)}</span>`;
    main.innerHTML = `<div class="page-h"><div><h1>Staff</h1><p class="sub">SMEPro's own people, who sign in here with an email and password. Owners add people, reset passwords and change roles; the staff key on the service remains the recovery path.</p></div>${r.canManage ? '<button class="btn primary" id="newS">Add a person</button>' : ''}</div>
      <div class="panel"><div class="tablewrap"><table><thead><tr><th>Email</th><th>Name</th><th>Role</th><th>Status</th><th>Last sign-in</th><th></th></tr></thead><tbody>${r.items.map(x => `<tr><td class="mono">${esc(x.email)}${x.id === r.me ? ' <span class="tag">you</span>' : ''}</td><td>${esc(x.name || '')}</td><td>${roleTag(x)}</td><td><span class="tag ${x.status === 'active' ? (x.lockedUntil ? 'warn' : 'ok') : 'bad'}">${x.status === 'active' ? (x.lockedUntil ? 'locked' : (x.mustChange ? 'temporary password' : 'active')) : 'disabled'}</span></td><td class="muted">${x.lastSignInAt ? fmtT(x.lastSignInAt) : 'never'}</td><td><div class="actions">${r.canManage && x.id !== r.me ? `<button class="btn sm" data-reset="${esc(x.id)}">Reset password</button><button class="btn sm" data-role="${esc(x.id)}" data-to="${x.role === 'owner' ? 'staff' : 'owner'}">${x.role === 'owner' ? 'Make staff' : 'Make owner'}</button><button class="btn sm ${x.status === 'active' ? 'danger' : ''}" data-status="${esc(x.id)}" data-to="${x.status === 'active' ? 'disabled' : 'active'}">${x.status === 'active' ? 'Disable' : 'Enable'}</button>` : ''}</div></td></tr>`).join('') || `<tr><td colspan="6" class="empty">No staff accounts yet.${r.canManage ? ' Add the first person.' : ''}</td></tr>`}</tbody></table></div></div>
      ${r.canManage ? '<div class="panel"><h2>Log</h2><div id="staffLog" class="small muted">Loading</div></div>' : ''}`;
    const showTemp = (email, pw) => modal(`<h2>Temporary password</h2><p class="sub">Read this to ${esc(email)} or send it by a channel you trust. It works once: they choose their own password at their first sign-in. It is not shown again.</p><input type="text" readonly class="mono" value="${esc(pw)}" onclick="this.select()"><div class="modal-actions"><button class="btn primary" data-close>Done</button></div>`);
    $('#newS')?.addEventListener('click', () => modal(`<h2>Add a person</h2><p class="sub">They get a temporary password to sign in with once, then set their own.</p><div class="field"><label for="sEmail">Email</label><input type="email" id="sEmail"></div><div class="field"><label for="sName">Name</label><input type="text" id="sName" maxlength="120"></div><div class="field"><label for="sRole">Role</label><select id="sRole"><option value="staff">Staff (operate the Vault)</option><option value="owner">Owner (also manages staff)</option></select></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Add</button></div><div class="small muted" id="mErr"></div>`, root => $('#ok', root).addEventListener('click', async () => {
      try { const x = await api('/staff', { body: { email: $('#sEmail', root).value, name: $('#sName', root).value, role: $('#sRole', root).value } }); closeModal(); showTemp(x.staff.email, x.tempPassword); viewStaff(main); } catch (e) { $('#mErr', root).textContent = e.message; }
    })));
    $$('[data-reset]', main).forEach(b => b.addEventListener('click', async () => { const row = r.items.find(x => x.id === b.dataset.reset); if (!confirm(`Reset the password of ${row.email}? Their sessions are signed out.`)) return; try { const x = await api('/staff/' + b.dataset.reset, { method: 'PATCH', body: { resetPassword: true } }); showTemp(x.staff.email, x.tempPassword); viewStaff(main); } catch (e) { toast(e.message, 'bad'); } }));
    $$('[data-role]', main).forEach(b => b.addEventListener('click', async () => { try { await api('/staff/' + b.dataset.role, { method: 'PATCH', body: { role: b.dataset.to } }); toast('Role changed'); viewStaff(main); } catch (e) { toast(e.message, 'bad'); } }));
    $$('[data-status]', main).forEach(b => b.addEventListener('click', async () => { try { await api('/staff/' + b.dataset.status, { method: 'PATCH', body: { status: b.dataset.to } }); toast(b.dataset.to === 'disabled' ? 'Disabled' : 'Enabled'); viewStaff(main); } catch (e) { toast(e.message, 'bad'); } }));
    if (r.canManage) { try { const log = await api('/staff/log'); $('#staffLog').innerHTML = log.items.length ? `<div class="tablewrap"><table><thead><tr><th>When</th><th>Who</th><th>What</th><th>Detail</th></tr></thead><tbody>${log.items.map(l => `<tr><td class="muted">${fmtT(l.at)}</td><td class="mono">${esc(l.email || (l.staff_id ? l.staff_id : 'staff key'))}</td><td>${esc(l.action)}</td><td class="mono small">${esc(l.detail || '')}</td></tr>`).join('')}</tbody></table></div>` : 'Nothing yet.'; } catch (e) { $('#staffLog').textContent = e.message; } }
  }

  // ---------- overview ----------
  async function viewOverview(main) {
    const o = await api('/overview');
    main.innerHTML = `<div class="page-h"><div><h1>Overview</h1><p class="sub">The whole service at a glance. OCR provider: <b>${esc(o.ocr)}</b>.</p></div></div>
      <div class="cards">${[['Tenants', o.tenants], ['Workspaces', o.workspaces], ['Documents', o.documents], ['Pages indexed', o.pages], ['Open batches', o.openBatches], ['Awaiting OCR', o.awaitingOcr, o.awaitingOcr ? 'warn' : ''], ['Failed files', o.failed, o.failed ? 'bad' : ''], ['Folders on paper', o.paperFolders], ['Scan requests open', o.scanRequests, o.scanRequests ? 'warn' : ''], ['Dead letters', o.deadLetters, o.deadLetters ? 'bad' : ''], ['Active connections', o.connections]].map(([k, v, c]) => `<div class="card ${c || ''}"><div class="v">${fmtN(v)}</div><div class="k">${k}</div></div>`).join('')}</div>
      <div class="panel"><h2>Where to start</h2><p>Create a tenant (the customer), add the people who may connect Ricorsa (their Vault email), create a workspace and a matter, then open a batch and upload files, or hand the batch key to the uploader script for a folder tree. Paper goes in as boxes and folders under the workspace's Inventory.</p></div>`;
  }

  // ---------- tenants ----------
  async function viewTenants(main) {
    const r = await api('/tenants');
    main.innerHTML = `<div class="page-h"><div><h1>Tenants and people</h1><p class="sub">A tenant is one customer: a firm or a program. Its people sign in to VDRPros with these emails and connect Ricorsa with them.</p></div><button class="btn primary" id="newT">New tenant</button></div>
      <div class="panel"><div class="tablewrap"><table><thead><tr><th>Tenant</th><th>Slug</th><th class="n">Workspaces</th><th class="n">People</th><th>Created</th></tr></thead><tbody>${r.items.map(t => `<tr data-open="#/tenant/${esc(t.id)}"><td><b>${esc(t.name)}</b></td><td class="mono">${esc(t.slug)}</td><td class="n">${fmtN(t.workspaces)}</td><td class="n">${fmtN(t.people)}</td><td class="muted">${fmtT(t.created_at)}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No tenants yet.</td></tr>'}</tbody></table></div></div>`;
    wireOpen(main);
    $('#newT').addEventListener('click', () => modal(`<h2>New tenant</h2><p class="sub">The customer's name; a short slug is made from it.</p><div class="field"><label for="tn">Name</label><input type="text" id="tn" maxlength="120" placeholder="e.g. Harper & Vance LLP"></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Create</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { const t = await api('/tenants', { body: { name: $('#tn').value } }); closeModal(); location.hash = '#/tenant/' + t.tenant.id; } catch (e) { toast(e.message, 'bad'); } })));
  }
  async function viewTenant(main, r) {
    const [ts, users, ws, conns, codes] = await Promise.all([api('/tenants'), api('/users?tenant=' + r.id), api('/workspaces?tenant=' + r.id), api('/connections?tenant=' + r.id), api('/codes?tenant=' + r.id).catch(() => ({ items: [], mail: true }))]);
    const t = ts.items.find(x => x.id === r.id); if (!t) throw new Error('No such tenant');
    main.innerHTML = `<div class="page-h"><div><h1>${esc(t.name)}</h1><p class="sub mono">${esc(t.slug)} · ${esc(t.id)}</p></div><div class="row"><button class="btn" id="verify">Verify receipt chain</button><button class="btn" id="receipts">Receipts</button><button class="btn" id="access">Access log</button></div></div>
      <div class="panel"><h2>People <button class="btn sm primary" id="newU">Add person</button></h2><div class="tablewrap"><table><thead><tr><th>Email</th><th>Name</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${users.items.map(u => `<tr><td class="mono">${esc(u.email)}</td><td>${esc(u.name || '')}</td><td><select data-role="${esc(u.id)}">${['owner', 'admin', 'contributor', 'reviewer', 'viewer'].map(x => `<option ${x === u.role ? 'selected' : ''}>${x}</option>`).join('')}</select></td><td><span class="tag ${u.status === 'active' ? 'ok' : 'bad'}">${esc(u.status)}</span></td><td><button class="btn sm" data-dis="${esc(u.id)}" data-st="${u.status === 'active' ? 'disabled' : 'active'}">${u.status === 'active' ? 'Disable' : 'Enable'}</button></td></tr>`).join('') || '<tr><td colspan="5" class="empty">Nobody yet. Add the people who will connect Ricorsa, with the email they use for the Vault.</td></tr>'}</tbody></table></div><p class="small muted">Owners and admins may share every workspace of the tenant with Ricorsa; others only the workspaces they are members of.</p>${!codes.mail ? `<div class="codes"><h3>Sign-in codes waiting</h3><p class="small muted">No mail provider is set up yet (RESEND_API_KEY), so codes requested from Ricorsa are shown here for ten minutes instead of being emailed. Read the code to the person.</p>${codes.items.length ? `<table><thead><tr><th>Email</th><th>Code</th><th>From</th><th>Expires</th></tr></thead><tbody>${codes.items.map(x => `<tr><td class="mono">${esc(x.email)}</td><td class="mono code">${esc(x.code)}</td><td>${esc(x.client)}</td><td class="muted">${esc(fmtT(x.expires_at))}</td></tr>`).join('')}</tbody></table>` : '<p class="small muted">None right now. Reload this page after a person presses Connect in Ricorsa.</p>'}</div>` : ''}</div>
      <div class="panel"><h2>Workspaces <button class="btn sm primary" id="newW">New workspace</button></h2><div class="tablewrap"><table><thead><tr><th>Workspace</th><th class="n">Documents</th><th class="n">Pages</th><th class="n">Folders on paper</th></tr></thead><tbody>${ws.items.map(w => `<tr data-open="#/workspace/${esc(w.id)}"><td><b>${esc(w.name)}</b><div class="small muted">${esc(w.description || '')}</div></td><td class="n">${fmtN(w.doc_count)}</td><td class="n">${fmtN(w.page_count)}</td><td class="n">${fmtN(w.paper_folders)}</td></tr>`).join('') || '<tr><td colspan="4" class="empty">No workspaces yet.</td></tr>'}</tbody></table></div></div>
      <div class="panel"><h2>Connections</h2><div class="tablewrap"><table><thead><tr><th>Client</th><th>Person</th><th>Workspaces</th><th>Status</th><th>Last used</th><th></th></tr></thead><tbody>${conns.items.map(c => `<tr><td>${esc(c.client)}${c.label ? ` <span class="muted">· ${esc(c.label)}</span>` : ''}</td><td class="mono">${esc(c.email)}</td><td class="mono small">${esc(JSON.parse(c.workspace_ids).join(', '))}</td><td><span class="tag ${c.status === 'active' ? 'ok' : ''}">${esc(c.status)}</span></td><td class="muted">${fmtT(c.last_used_at)}</td><td>${c.status === 'active' ? `<button class="btn sm danger" data-revoke="${esc(c.id)}">Revoke</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No connections yet. People connect from inside Ricorsa.</td></tr>'}</tbody></table></div></div>
      <div id="extra"></div>`;
    wireOpen(main);
    $$('[data-role]').forEach(s => s.addEventListener('change', async () => { try { await api('/users/' + s.dataset.role, { method: 'PATCH', body: { role: s.value } }); toast('Role saved'); } catch (e) { toast(e.message, 'bad'); } }));
    $$('[data-dis]').forEach(b => b.addEventListener('click', async () => { try { await api('/users/' + b.dataset.dis, { method: 'PATCH', body: { status: b.dataset.st } }); render(); } catch (e) { toast(e.message, 'bad'); } }));
    $$('[data-revoke]').forEach(b => b.addEventListener('click', async () => { if (!confirm('Revoke this connection? Ricorsa will lose access at once.')) return; try { await api('/connections/' + b.dataset.revoke + '/revoke', { body: {} }); render(); } catch (e) { toast(e.message, 'bad'); } }));
    $('#newU').addEventListener('click', () => modal(`<h2>Add a person</h2><p class="sub">The email they use for the Vault. Ricorsa's one-time code goes to it.</p><div class="field"><label for="ue">Email</label><input type="email" id="ue"></div><div class="field"><label for="un">Name</label><input type="text" id="un"></div><div class="field"><label for="ur">Role</label><select id="ur">${['owner', 'admin', 'contributor', 'reviewer', 'viewer'].map(x => `<option ${x === 'admin' ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Add</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { await api('/users', { body: { tenantId: t.id, email: $('#ue').value, name: $('#un').value, role: $('#ur').value } }); closeModal(); render(); } catch (e) { toast(e.issues ? e.issues.join('; ') : e.message, 'bad'); } })));
    $('#newW').addEventListener('click', () => modal(`<h2>New workspace</h2><div class="field"><label for="wn">Name</label><input type="text" id="wn" placeholder="e.g. Asbestos docket, Missouri"></div><div class="field"><label for="wd">Description</label><input type="text" id="wd"></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Create</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { const w = await api('/workspaces', { body: { tenantId: t.id, name: $('#wn').value, description: $('#wd').value } }); closeModal(); location.hash = '#/workspace/' + w.workspace.id; } catch (e) { toast(e.message, 'bad'); } })));
    $('#verify').addEventListener('click', async () => { try { const v = await api('/receipts/verify?tenant=' + t.id); toast(v.ok ? `Receipt chain intact: ${fmtN(v.count)} receipts` : `Chain broken at receipt ${v.brokenAt}`, v.ok ? '' : 'bad'); } catch (e) { toast(e.message, 'bad'); } });
    $('#receipts').addEventListener('click', async () => { const rr = await api('/receipts?tenant=' + t.id + '&limit=200'); $('#extra').innerHTML = `<div class="panel"><h2>Receipts (latest 200)</h2><div class="tablewrap"><table><thead><tr><th class="n">#</th><th>Kind</th><th>Subject</th><th>Hash</th><th>When</th></tr></thead><tbody>${rr.items.map(x => `<tr><td class="n">${x.seq}</td><td>${esc(x.kind)}</td><td class="mono small">${esc(x.subject || '')}</td><td class="mono small" title="${esc(x.hash)}">${esc(x.hash.slice(0, 16))}…</td><td class="muted">${fmtT(x.at)}</td></tr>`).join('')}</tbody></table></div></div>`; });
    $('#access').addEventListener('click', async () => { const rr = await api('/access-log?tenant=' + t.id); $('#extra').innerHTML = `<div class="panel"><h2>Access log (latest 300)</h2><div class="tablewrap"><table><thead><tr><th>When</th><th>Action</th><th>Document</th><th>Connection</th><th>Detail</th></tr></thead><tbody>${rr.items.map(x => `<tr><td class="muted">${fmtT(x.at)}</td><td>${esc(x.action)}</td><td class="mono small">${x.doc_id ? `<a href="#/document/${esc(x.doc_id)}">${esc(x.doc_id.split('.').pop())}</a>` : ''}</td><td class="mono small">${esc(x.connection_id || x.user_id || '')}</td><td class="small">${esc(x.detail || '')}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">Nothing read yet.</td></tr>'}</tbody></table></div></div>`; });
  }

  // ---------- workspaces ----------
  async function viewWorkspaces(main) {
    const r = await api('/workspaces');
    main.innerHTML = `<div class="page-h"><div><h1>Workspaces</h1><p class="sub">Every workspace across tenants.</p></div></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Workspace</th><th>Tenant</th><th class="n">Documents</th><th class="n">Pages</th><th class="n">Paper folders</th></tr></thead><tbody>${r.items.map(w => `<tr data-open="#/workspace/${esc(w.id)}"><td><b>${esc(w.name)}</b></td><td>${esc(w.tenant || '')}</td><td class="n">${fmtN(w.doc_count)}</td><td class="n">${fmtN(w.page_count)}</td><td class="n">${fmtN(w.paper_folders)}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No workspaces yet.</td></tr>'}</tbody></table></div></div>`;
    wireOpen(main);
  }
  async function viewWorkspace(main, r) {
    const d = await api('/workspaces/' + r.id);
    const w = d.workspace; const tab = r.query.tab || 'documents';
    const tabs = [['documents', 'Documents and search'], ['matters', `Matters (${d.matters.length})`], ['inventory', `Paper inventory (${d.boxes.length} boxes)`], ['batches', `Batches (${d.batches.length})`], ['requests', `Scan requests (${d.requests.filter(x => x.status === 'requested' || x.status === 'scanning').length})`], ['shards', `Shards (${d.shards.length})`]];
    main.innerHTML = `<div class="page-h"><div><h1>${esc(w.name)}</h1><p class="sub"><a href="#/tenant/${esc(w.tenant_id)}">Tenant</a> · workspace_id <span class="mono">${esc(w.id)}</span> · ${fmtN(w.doc_count)} documents, ${fmtN(w.page_count)} pages, ${fmtN(w.paper_folders)} folders on paper</p></div></div>
      <nav class="nav" style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:12px">${tabs.map(([k, l]) => `<a href="#/workspace/${esc(w.id)}?tab=${k}" class="${tab === k ? 'on' : ''}">${l}</a>`).join('')}</nav><div id="tab"></div>`;
    const box = $('#tab');
    if (tab === 'documents') await tabDocuments(box, w, d);
    else if (tab === 'matters') tabMatters(box, w, d);
    else if (tab === 'inventory') tabInventory(box, w, d);
    else if (tab === 'batches') tabBatches(box, w, d);
    else if (tab === 'requests') tabRequests(box, w, d);
    else tabShards(box, w, d);
  }
  async function tabDocuments(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Search</h2><div class="row"><input type="search" id="q" placeholder="Words or quoted phrases: LaCygne, &quot;joint compound&quot;, Evergy"><select id="kind" class="fixed" style="width:170px"><option value="">Any kind</option>${['transcript', 'summary', 'exhibit', 'medical', 'correspondence', 'registry', 'invoice', 'pleading', 'document'].map(k => `<option>${k}</option>`).join('')}</select><select id="matter" class="fixed" style="width:200px"><option value="">Any matter</option>${d.matters.map(m => `<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select><button class="btn primary fixed" id="go">Search</button></div><div class="hits" id="hits"></div></div>
      <div class="panel"><h2>Latest documents <span class="row" style="flex:0 0 auto;gap:6px"><select id="st" class="fixed" style="width:170px"><option value="">Any status</option>${['indexed', 'received', 'processing', 'awaiting_ocr', 'needs_conversion', 'failed'].map(s => `<option>${s}</option>`).join('')}</select></span></h2><div id="docs"><div class="empty">Loading</div></div></div>`;
    const search = async () => { const q = $('#q').value.trim(); if (!q) return; $('#hits').innerHTML = '<div class="empty">Searching</div>'; try { const r = await api(`/search?workspace=${w.id}&q=${encodeURIComponent(q)}&kind=${encodeURIComponent($('#kind').value)}&matter=${encodeURIComponent($('#matter').value)}`); $('#hits').innerHTML = r.hits.length ? `<p class="small muted">${r.hits.length} pages, ${r.searched} shard${r.searched === 1 ? '' : 's'}, matched on ${esc(r.mode)}</p>` + r.hits.map(h => `<div class="hit"><b><a href="#/document/${esc(h.docId)}">${esc(h.name)}</a> <span class="tag">${esc(h.kind)}</span> page ${h.page}${h.pages ? ` of ${h.pages}` : ''}</b><div class="meta">${[h.witness ? 'witness ' + h.witness : '', h.volume ? 'Vol. ' + h.volume : '', h.docDate || '', h.matter || '', h.folder ? 'from ' + h.folder : ''].filter(Boolean).map(esc).join(' · ')}</div><div class="snip">${esc(h.snippet || '(no text on this page)')}</div></div>`).join('') : '<div class="empty">Nothing matched.</div>'; } catch (e) { $('#hits').innerHTML = `<div class="empty">${esc(e.message)}</div>`; } };
    $('#go').addEventListener('click', search); $('#q').addEventListener('keydown', e => { if (e.key === 'Enter') search(); });
    const list = async () => { const r = await api(`/workspaces/${w.id}/documents?limit=60&status=${encodeURIComponent($('#st').value)}`); $('#docs').innerHTML = `<div class="tablewrap"><table><thead><tr><th>Name</th><th>Kind</th><th>Status</th><th class="n">Pages</th><th class="n">Size</th><th>Received</th></tr></thead><tbody>${r.items.map(x => `<tr data-open="#/document/${esc(x.id)}"><td><b>${esc(x.name)}</b><div class="small muted mono">${esc(x.path || '')}</div></td><td>${esc(x.kind)}${x.witness ? `<div class="small muted">${esc(x.witness)}</div>` : ''}</td><td>${statusTag(x.status)}${x.error ? `<div class="small muted">${esc(x.error)}</div>` : ''}</td><td class="n">${fmtN(x.pages)}</td><td class="n">${fmtB(x.size)}</td><td class="muted">${fmtT(x.created_at)}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No documents yet. Open a batch to upload some.</td></tr>'}</tbody></table></div><p class="small muted">${fmtN(r.total)} in total.</p>`; wireOpen($('#docs')); };
    $('#st').addEventListener('change', list); await list();
  }
  function statusTag(s) { const cls = s === 'indexed' ? 'ok' : s === 'failed' ? 'bad' : (s === 'awaiting_ocr' || s === 'needs_conversion') ? 'warn' : ''; return `<span class="tag ${cls}">${esc(s.replace(/_/g, ' '))}</span>`; }
  function tabMatters(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Matters <button class="btn sm primary" id="newM">New matter</button></h2><div class="tablewrap"><table><thead><tr><th>Matter</th><th>Caption</th><th>Court</th><th class="n">Documents</th><th>matter_id</th></tr></thead><tbody>${d.matters.map(m => `<tr><td><b>${esc(m.name)}</b></td><td>${esc(m.caption || '')}</td><td>${esc(m.court || '')}</td><td class="n">${fmtN(m.doc_count)}</td><td class="mono small">${esc(m.id)}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No matters yet. A matter is a case or a deal inside the workspace.</td></tr>'}</tbody></table></div></div>
      <div class="panel"><h2>Members <button class="btn sm" id="newMem">Add member</button></h2><div class="tablewrap"><table><thead><tr><th>Email</th><th>Name</th><th>Role</th><th></th></tr></thead><tbody>${d.members.map(m => `<tr><td class="mono">${esc(m.email)}</td><td>${esc(m.name || '')}</td><td>${esc(m.role)}</td><td><button class="btn sm" data-rm="${esc(m.user_id)}">Remove</button></td></tr>`).join('') || '<tr><td colspan="4" class="empty">No members. Tenant owners and admins see every workspace without being listed here.</td></tr>'}</tbody></table></div></div>`;
    $('#newM').addEventListener('click', () => modal(`<h2>New matter</h2><div class="field"><label for="mn">Name</label><input type="text" id="mn" placeholder="e.g. Smith v. Kaiser Gypsum et al."></div><div class="field"><label for="mc">Caption</label><input type="text" id="mc"></div><div class="field"><label for="mco">Court</label><input type="text" id="mco"></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Create</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { await api('/matters', { body: { workspaceId: w.id, name: $('#mn').value, caption: $('#mc').value, court: $('#mco').value } }); closeModal(); render(); } catch (e) { toast(e.message, 'bad'); } })));
    $('#newMem').addEventListener('click', async () => { const users = await api('/users?tenant=' + w.tenant_id); modal(`<h2>Add a member</h2><div class="field"><label for="mu">Person</label><select id="mu">${users.items.map(u => `<option value="${esc(u.id)}">${esc(u.email)}${u.name ? ' · ' + esc(u.name) : ''}</option>`).join('')}</select></div><div class="field"><label for="mr">Role in this workspace</label><select id="mr">${['owner', 'admin', 'contributor', 'reviewer', 'viewer'].map(x => `<option ${x === 'viewer' ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Add</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { await api('/members', { body: { workspaceId: w.id, userId: $('#mu').value, role: $('#mr').value } }); closeModal(); render(); } catch (e) { toast(e.message, 'bad'); } })); });
    $$('[data-rm]').forEach(b => b.addEventListener('click', async () => { await api(`/members/${w.id}/${b.dataset.rm}`, { method: 'DELETE' }); render(); }));
  }
  function tabInventory(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Boxes <button class="btn sm primary" id="addBoxes">Add boxes and folders</button></h2><p class="small muted">Barcode every box and folder in the records room; the label is what Ricorsa can find it by before it is scanned. Location is shelf-level.</p><div class="tablewrap"><table><thead><tr><th>Barcode</th><th>Label</th><th>Custodian</th><th>Dates</th><th>Location</th><th>Status</th><th class="n">Folders</th><th class="n">Pages (est.)</th></tr></thead><tbody>${d.boxes.map(b => `<tr data-box="${esc(b.id)}"><td class="mono">${esc(b.barcode)}</td><td><b>${esc(b.label)}</b></td><td>${esc(b.custodian || '')}</td><td class="small">${esc([b.date_from, b.date_to].filter(Boolean).join(' to '))}</td><td class="small">${esc(b.location || '')}</td><td>${statusTag(b.status)}</td><td class="n">${fmtN(b.folder_count)}</td><td class="n">${b.pages_est ? fmtN(b.pages_est) : ''}</td></tr>`).join('') || '<tr><td colspan="8" class="empty">No boxes yet.</td></tr>'}</tbody></table></div></div><div id="folders"></div>`;
    $$('[data-box]').forEach(tr => { tr.style.cursor = 'pointer'; tr.addEventListener('click', async () => { const r = await api('/boxes/' + tr.dataset.box); $('#folders').innerHTML = `<div class="panel"><h2>Folders in ${esc(r.box.label)} <span class="mono small">${esc(r.box.barcode)}</span></h2><div class="tablewrap"><table><thead><tr><th>Barcode</th><th>Label</th><th>Status</th><th class="n">Pages (est.)</th><th class="n">Documents</th><th></th></tr></thead><tbody>${r.folders.map(f => `<tr><td class="mono">${esc(f.barcode)}</td><td>${esc(f.label)}</td><td>${statusTag(f.status)}</td><td class="n">${f.pages_est ? fmtN(f.pages_est) : ''}</td><td class="n">${fmtN(f.doc_count)}</td><td class="row" style="gap:4px">${f.status === 'paper' ? `<button class="btn sm" data-req="${esc(f.id)}">Request scan</button>` : ''}${f.status !== 'digitised' ? `<button class="btn sm" data-batch="${esc(f.id)}" data-label="${esc(f.label)}">Open scan batch</button>` : ''}<span class="mono small muted">folder_id ${esc(f.id)}</span></td></tr>`).join('') || '<tr><td colspan="6" class="empty">No folders recorded for this box.</td></tr>'}</tbody></table></div></div>`; $$('[data-req]').forEach(b => b.addEventListener('click', async () => { try { const x = await api('/scan-requests', { body: { workspaceId: w.id, folderId: b.dataset.req } }); toast(`Scan requested, due ${fmtT(x.dueAt)}`); tr.click(); } catch (e) { toast(e.message, 'bad'); } })); $$('[data-batch]').forEach(b => b.addEventListener('click', async () => { try { const x = await api('/batches', { body: { workspaceId: w.id, folderId: b.dataset.batch, kind: 'scan', name: 'Scan of ' + b.dataset.label } }); location.hash = '#/batch/' + x.batch.id + '?key=' + encodeURIComponent(x.intakeKey); } catch (e) { toast(e.message, 'bad'); } })); }); });
    $('#addBoxes').addEventListener('click', () => modal(`<h2>Add boxes and folders</h2><p class="sub">One box per line: <span class="mono">barcode | label | custodian | date from | date to | location | pages estimate</span>. Folders for the box on the following lines, indented with two spaces: <span class="mono">  barcode | label | pages estimate</span>.</p><textarea id="inv" rows="12" placeholder="B-1183 | Smith exposure files, sheet metal 1968 to 1992 | J. Alvarez | 1968 | 1992 | Row 4, shelf C | 2400\n  F-1183-01 | Union dispatch records | 300\n  F-1183-02 | Employer correspondence, Natkin | 450"></textarea><div class="field"><label for="im">Matter (optional)</label><select id="im"><option value="">None</option>${d.matters.map(m => `<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Add</button></div>`, root => $('#ok', root).addEventListener('click', async () => {
      const lines = $('#inv').value.split('\n'); const boxes = []; let cur = null;
      for (const raw of lines) { if (!raw.trim()) continue; const parts = raw.replace(/^\s+/, '').split('|').map(s => s.trim()); if (/^\s{2,}/.test(raw) && cur) { cur.folders.push({ barcode: parts[0], label: parts[1] || parts[0], pagesEst: parts[2] ? +parts[2] : undefined }); } else { cur = { barcode: parts[0], label: parts[1] || parts[0], custodian: parts[2] || undefined, dateFrom: parts[3] || undefined, dateTo: parts[4] || undefined, location: parts[5] || undefined, pagesEst: parts[6] ? +parts[6] : undefined, matterId: $('#im').value || undefined, folders: [] }; boxes.push(cur); } }
      if (!boxes.length) { toast('Nothing to add', 'bad'); return; }
      try { const r = await api('/boxes', { body: { workspaceId: w.id, boxes } }); closeModal(); toast(`${r.boxes} boxes, ${r.folders} folders recorded`); render(); } catch (e) { toast(e.issues ? e.issues.join('; ') : e.message, 'bad'); }
    })));
  }
  function tabBatches(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Batches <button class="btn sm primary" id="newB">Open a batch</button></h2><p class="small muted">A batch is one delivery. Upload from this screen, or hand its key to the uploader script for a whole folder tree. Seal it when everything is in.</p><div class="tablewrap"><table><thead><tr><th>Batch</th><th>Kind</th><th>Status</th><th class="n">Expected</th><th class="n">Received</th><th class="n">Duplicates</th><th class="n">Done</th><th class="n">Awaiting OCR</th><th class="n">Failed</th><th>Opened</th></tr></thead><tbody>${d.batches.map(b => `<tr data-open="#/batch/${esc(b.id)}"><td><b>${esc(b.name)}</b></td><td>${esc(b.kind)}</td><td>${statusTag(b.status)}</td><td class="n">${fmtN(b.files_expected)}</td><td class="n">${fmtN(b.files_received)}</td><td class="n">${fmtN(b.files_duplicate)}</td><td class="n">${fmtN(b.files_done)}</td><td class="n">${fmtN(b.files_awaiting_ocr)}</td><td class="n">${fmtN(b.files_failed)}</td><td class="muted">${fmtT(b.created_at)}</td></tr>`).join('') || '<tr><td colspan="10" class="empty">No batches yet.</td></tr>'}</tbody></table></div></div>`;
    wireOpen(box);
    $('#newB').addEventListener('click', () => modal(`<h2>Open a batch</h2><div class="field"><label for="bn">Name</label><input type="text" id="bn" placeholder="e.g. Pilot load, September"></div><div class="field"><label for="bk">Kind</label><select id="bk"><option value="electronic">Electronic files</option><option value="scan">Scanned paper</option><option value="app">From the VDRPros app</option></select></div><div class="field"><label for="bm">Matter (optional)</label><select id="bm"><option value="">None</option>${d.matters.map(m => `<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Open</button></div>`, root => $('#ok', root).addEventListener('click', async () => { try { const r = await api('/batches', { body: { workspaceId: w.id, name: $('#bn').value, kind: $('#bk').value, matterId: $('#bm').value || undefined } }); closeModal(); location.hash = '#/batch/' + r.batch.id + '?key=' + encodeURIComponent(r.intakeKey); } catch (e) { toast(e.message, 'bad'); } })));
  }
  function tabRequests(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Scan requests</h2><div class="tablewrap"><table><thead><tr><th>Folder or box</th><th>Via</th><th>Note</th><th>Status</th><th>Due</th><th>Requested</th><th></th></tr></thead><tbody>${d.requests.map(r => `<tr><td><b>${esc(r.folder || r.box || '')}</b></td><td>${esc(r.via)}</td><td class="small">${esc(r.note || '')}</td><td>${statusTag(r.status)}</td><td class="${r.due_at && r.due_at < Date.now() && (r.status === 'requested' || r.status === 'scanning') ? 'tag bad' : 'muted'}">${fmtT(r.due_at)}</td><td class="muted">${fmtT(r.created_at)}</td><td><select data-rs="${esc(r.id)}">${['requested', 'scanning', 'done', 'declined'].map(s => `<option ${s === r.status ? 'selected' : ''}>${s}</option>`).join('')}</select></td></tr>`).join('') || '<tr><td colspan="7" class="empty">No requests.</td></tr>'}</tbody></table></div></div>`;
    $$('[data-rs]').forEach(s => s.addEventListener('change', async () => { try { await api('/scan-requests/' + s.dataset.rs, { method: 'PATCH', body: { status: s.value } }); toast('Saved'); } catch (e) { toast(e.message, 'bad'); } }));
  }
  function tabShards(box, w, d) {
    box.innerHTML = `<div class="panel"><h2>Search shards</h2><p class="small muted">One SQLite index per slice of the workspace. A shard closes to new documents when it nears its size and the next one opens.</p><div class="tablewrap"><table><thead><tr><th class="n">#</th><th>Status</th><th class="n">Documents</th><th class="n">Indexed</th><th class="n">Waiting</th><th class="n">Failed</th><th class="n">Pages</th><th class="n">Size</th></tr></thead><tbody>${d.shards.map(s => `<tr><td class="n">${s.n}</td><td>${statusTag(s.status)}</td><td class="n">${fmtN(s.live ? s.live.docs : s.docs)}</td><td class="n">${fmtN(s.live ? s.live.indexed : '')}</td><td class="n">${fmtN(s.live ? s.live.awaiting : '')}</td><td class="n">${fmtN(s.live ? s.live.failed : '')}</td><td class="n">${fmtN(s.live ? s.live.pages : s.pages)}</td><td class="n">${fmtB(s.live ? s.live.bytes : s.bytes)}</td></tr>`).join('') || '<tr><td colspan="8" class="empty">No shards until the first file arrives.</td></tr>'}</tbody></table></div></div>`;
  }

  // ---------- batch: status and browser upload ----------
  async function viewBatch(main, r) {
    const d = await api('/batches/' + r.id); const b = d.batch; const key = r.query.key;
    main.innerHTML = `<div class="page-h"><div><h1>${esc(b.name)}</h1><p class="sub"><a href="#/workspace/${esc(b.workspace_id)}?tab=batches">Workspace</a> · ${esc(b.kind)} · ${statusTag(b.status)} · opened ${fmtT(b.created_at)}${b.seal ? ` · seal <span class="mono">${esc(b.seal.slice(0, 20))}…</span>` : ''}</p></div><div class="row">${b.status === 'open' ? `<button class="btn" id="seal">Seal batch</button>` : ''}<button class="btn" id="refresh">Refresh</button></div></div>
      <div class="cards">${[['Expected', b.files_expected], ['Received', b.files_received], ['Duplicates', b.files_duplicate], ['Read and indexed', b.files_done], ['Awaiting OCR', b.files_awaiting_ocr, b.files_awaiting_ocr ? 'warn' : ''], ['Failed', b.files_failed, b.files_failed ? 'bad' : ''], ['Bytes', fmtB(b.bytes)]].map(([k, v, c]) => `<div class="card ${c || ''}"><div class="v">${typeof v === 'number' ? fmtN(v) : v}</div><div class="k">${k}</div></div>`).join('')}</div>
      ${key ? `<div class="panel"><h2>Batch key</h2><p class="small">This key is shown once. The uploader script uses it: <span class="mono">node scripts/upload.mjs --url ${esc(location.origin)} --batch ${esc(b.id)} --key … ./folder</span></p><input type="text" readonly value="${esc(key)}" class="mono" onclick="this.select()"></div>` : ''}
      ${b.status === 'open' ? `<div class="panel"><h2>Upload from this browser</h2><p class="small muted">Pick files or a whole folder. Each file is hashed here first, so duplicates are skipped and the Vault checks what it received against that hash. Fine for a pilot; millions of files go through the uploader script or a bulk sync.</p><div class="row"><input type="file" id="files" multiple class="fixed"><input type="file" id="dir" webkitdirectory multiple class="fixed"><button class="btn primary fixed" id="up" disabled>Upload</button></div><div class="progress"><i id="bar"></i></div><pre class="log" id="log">Nothing uploaded yet.</pre></div>` : ''}
      ${d.deadLetters.length ? `<div class="panel"><h2>Files that could not be processed</h2><div class="tablewrap"><table><thead><tr><th>Document</th><th>Stage</th><th>Error</th><th class="n">Attempts</th><th></th></tr></thead><tbody>${d.deadLetters.map(x => `<tr><td class="mono small"><a href="#/document/${esc(x.doc_id)}">${esc(x.doc_id.split('.').pop())}</a></td><td>${esc(x.stage)}</td><td class="small">${esc(x.error)}</td><td class="n">${x.attempts}</td><td><button class="btn sm" data-retry="${esc(x.id)}">Retry</button></td></tr>`).join('')}</tbody></table></div></div>` : ''}`;
    $('#refresh').addEventListener('click', render);
    const seal = $('#seal'); if (seal) seal.addEventListener('click', async () => { if (!confirm('Seal this batch? No more files can be added to it.')) return; try { const s = await api(`/batches/${b.id}/seal`, { body: {} }); toast(`Sealed: ${fmtN(s.files)} files${s.missing.length ? `, ${s.missing.length} listed in the manifest never arrived` : ''}`); render(); } catch (e) { toast(e.message, 'bad'); } });
    $$('[data-retry]').forEach(x => x.addEventListener('click', async () => { try { await api('/dead-letters/' + x.dataset.retry + '/retry', { body: {} }); toast('Queued again'); render(); } catch (e) { toast(e.message, 'bad'); } }));
    const picked = []; const upBtn = $('#up'); const log = m => { const el = $('#log'); if (el) { el.textContent = (el.textContent === 'Nothing uploaded yet.' ? '' : el.textContent + '\n') + m; el.scrollTop = el.scrollHeight; } };
    for (const id of ['files', 'dir']) { const inp = $('#' + id); if (inp) inp.addEventListener('change', () => { picked.length = 0; picked.push(...inp.files); upBtn.disabled = !picked.length; log(`${picked.length} file${picked.length === 1 ? '' : 's'} picked, ${fmtB([...picked].reduce((n, f) => n + f.size, 0))}`); }); }
    if (upBtn) upBtn.addEventListener('click', async () => {
      upBtn.disabled = true; const bar = $('#bar'); const files = [...picked]; const manifest = [];
      log('Hashing');
      for (const f of files) { const buf = await f.arrayBuffer(); const h = [...new Uint8Array(await crypto.subtle.digest('SHA-256', buf))].map(x => x.toString(16).padStart(2, '0')).join(''); f._sha = h; manifest.push({ path: f.webkitRelativePath || f.name, size: f.size, sha256: h }); }
      let known = {}; try { const m = await api(`/batches/${b.id}/manifest`, { body: { files: manifest } }); known = m.known || {}; log(`Manifest recorded: ${m.expected} files, ${Object.keys(known).length} already held`); } catch (e) { log('Manifest failed: ' + e.message); upBtn.disabled = false; return; }
      let done = 0, dup = 0, failed = 0; const queue = files.slice();
      const worker = async () => { for (;;) { const f = queue.shift(); if (!f) return; const path = f.webkitRelativePath || f.name; try { if (known[f._sha]) { dup++; } else { const r = await fetch(`/api/admin/batches/${b.id}/files?path=${encodeURIComponent(path)}&sha256=${f._sha}`, { method: 'PUT', body: f }); const j = await r.json(); if (!r.ok) throw new Error(j.error || r.status); if (j.duplicate) dup++; } done++; } catch (e) { failed++; log(`${path}: ${e.message}`); } bar.style.width = Math.round(((done + failed) / files.length) * 100) + '%'; } };
      await Promise.all([worker(), worker(), worker(), worker()]);
      log(`Uploaded ${done} (${dup} duplicates skipped), ${failed} failed. Files are being read now; refresh to watch the counts.`);
      setTimeout(render, 1500);
    });
  }

  // ---------- connections, dead letters, document ----------
  async function viewConnections(main) {
    const r = await api('/connections');
    main.innerHTML = `<div class="page-h"><div><h1>Connections</h1><p class="sub">Outside clients (Ricorsa) connected by people, limited to the workspaces they chose.</p></div></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Client</th><th>Person</th><th>Workspaces</th><th>Status</th><th>Created</th><th>Last used</th><th></th></tr></thead><tbody>${r.items.map(c => `<tr><td>${esc(c.client)}${c.label ? ` <span class="muted">· ${esc(c.label)}</span>` : ''}</td><td class="mono">${esc(c.email)}</td><td class="mono small">${esc(JSON.parse(c.workspace_ids).join(', '))}</td><td><span class="tag ${c.status === 'active' ? 'ok' : ''}">${esc(c.status)}</span></td><td class="muted">${fmtT(c.created_at)}</td><td class="muted">${fmtT(c.last_used_at)}</td><td>${c.status === 'active' ? `<button class="btn sm danger" data-revoke="${esc(c.id)}">Revoke</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">No connections yet.</td></tr>'}</tbody></table></div></div>`;
    $$('[data-revoke]').forEach(b => b.addEventListener('click', async () => { if (!confirm('Revoke this connection?')) return; await api('/connections/' + b.dataset.revoke + '/revoke', { body: {} }); render(); }));
  }
  async function viewDeadLetters(main) {
    const r = await api('/dead-letters');
    main.innerHTML = `<div class="page-h"><div><h1>Dead letters</h1><p class="sub">Files the pipeline could not finish after its retries. Nothing is dropped silently.</p></div></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Document</th><th>Workspace</th><th>Stage</th><th>Error</th><th class="n">Attempts</th><th>When</th><th></th></tr></thead><tbody>${r.items.map(x => `<tr><td class="mono small"><a href="#/document/${esc(x.doc_id)}">${esc(x.doc_id.split('.').pop())}</a></td><td class="mono small"><a href="#/workspace/${esc(x.workspace_id)}">${esc(x.workspace_id)}</a></td><td>${esc(x.stage)}</td><td class="small">${esc(x.error)}</td><td class="n">${x.attempts}</td><td class="muted">${fmtT(x.created_at)}</td><td><button class="btn sm" data-retry="${esc(x.id)}">Retry</button></td></tr>`).join('') || '<tr><td colspan="7" class="empty">Nothing here. Good.</td></tr>'}</tbody></table></div></div>`;
    $$('[data-retry]').forEach(x => x.addEventListener('click', async () => { try { await api('/dead-letters/' + x.dataset.retry + '/retry', { body: {} }); toast('Queued again'); render(); } catch (e) { toast(e.message, 'bad'); } }));
  }
  async function viewDocument(main, r) {
    const d = await api('/documents/' + r.id); const x = d.doc;
    let extra = null; try { extra = x.extra ? JSON.parse(x.extra) : null; } catch { extra = null; }
    const defendants = x.defendants ? JSON.parse(x.defendants) : [];
    main.innerHTML = `<div class="page-h"><div><h1>${esc(x.name)}</h1><p class="sub"><a href="#/workspace/${esc(x.workspace_id)}">Workspace</a> · ${statusTag(x.status)} · ${esc(x.kind)}${x.witness ? ` · witness ${esc(x.witness)}` : ''}${x.volume ? ` · Vol. ${esc(x.volume)}` : ''}</p></div><div class="row"><a class="btn" href="${esc(d.link)}" target="_blank" rel="noopener">Open original</a><a class="btn" href="${esc(d.link)}&download=1">Download</a></div></div>
      <div class="panel"><h2>Facts</h2><div class="kv"><div>Document id</div><div class="mono small">${esc(x.id)}</div><div>Path as received</div><div class="mono small">${esc(x.path || '')}</div><div>SHA-256 seal</div><div class="mono small">${esc(x.sha256)}</div><div>Size and type</div><div>${fmtB(x.size)} · ${esc(x.mime)}</div><div>Pages / characters</div><div>${fmtN(x.pages)} / ${fmtN(x.chars)}</div><div>Date</div><div>${esc(x.doc_date || '')}</div><div>Matter</div><div class="mono small">${esc(x.matter_id || '')}</div><div>Folder / box</div><div class="mono small">${esc(x.folder_id || '')} ${esc(x.box_id || '')}</div><div>Batch</div><div class="mono small"><a href="#/batch/${esc(x.batch_id)}">${esc(x.batch_id || '')}</a></div><div>OCR</div><div>${d.ocr ? `${esc(d.ocr.provider)}${d.ocr.confidence != null ? `, confidence ${d.ocr.confidence}` : ''}` : 'not needed'}</div>${x.error ? `<div>Note</div><div>${esc(x.error)}</div>` : ''}</div></div>
      ${defendants.length ? `<div class="panel"><h2>Defendants in the summary grid (${defendants.length})</h2><p class="small">${defendants.map(esc).join(' · ')}</p>${extra && extra.rows ? `<div class="tablewrap"><table><thead><tr>${Object.keys(extra.rows[0] || {}).slice(0, 8).map(k => `<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${extra.rows.slice(0, 40).map(row => `<tr>${Object.keys(extra.rows[0] || {}).slice(0, 8).map(k => `<td class="small">${esc(String(row[k] || '').slice(0, 160))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>` : ''}</div>` : ''}
      <div class="panel"><h2>Pages</h2><div class="tablewrap"><table><thead><tr><th class="n">Page</th><th class="n">Characters</th><th>Starts with</th></tr></thead><tbody>${d.pages.map(p => `<tr><td class="n">${p.page}</td><td class="n">${fmtN(p.chars)}</td><td class="small">${esc(p.preview)}</td></tr>`).join('') || '<tr><td colspan="3" class="empty">No text yet.</td></tr>'}</tbody></table></div></div>
      <div class="panel"><h2>Receipts</h2><div class="tablewrap"><table><thead><tr><th>Kind</th><th>Hash</th><th>When</th></tr></thead><tbody>${d.receipts.map(rc => `<tr><td>${esc(rc.kind)}</td><td class="mono small">${esc(rc.hash)}</td><td class="muted">${fmtT(rc.at)}</td></tr>`).join('')}</tbody></table></div></div>`;
  }

  function wireOpen(root) { $$('[data-open]', root).forEach(tr => tr.addEventListener('click', e => { if (e.target.closest('a, button, select, input')) return; location.hash = tr.dataset.open; })); }

  window.addEventListener('hashchange', render);
  (async () => { await loadSession(); render(); })();
})();
